      "tile_weight": 43.9
    },
    {
      "tile_id": 7,
      "tile_weight": 26.1
    },
    {
      "tile_id": 8,
      "tile_weight": 26.3
    },
    {
      "tile_id": 9,
      "tile_weight": 25.4
    },
    {
      "tile_id": 10,
      "tile_weight": 25.4
